using System;
using System.Collections.Immutable;
using System.Linq;
using System.Text.RegularExpressions;
using Extensions.Pack;
using Microsoft.AspNetCore.Mvc;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Minimal API")]
    [TestClass]
    public class RJIT_CR_MAPI_00011 : MinimalApiTestBase
    {
        [TestMethod]
        public void All_Used_Api_Versions_Have_To_Be_Registered_By_NewApiVersionSet()
        {
            // All api version mappings
            var hasVersionStatements = (from syntaxTree in ProductiveSyntaxTrees
                                        where syntaxTree.SyntaxTree.Contains(".HasApiVersion(")
                                        let matches = GlobalRegex.HasVersionRegex().Matches(syntaxTree.SyntaxTree)
                                        from match in matches
                                        where match.Success
                                        select new
                                        {
                                            Version = match.Groups[1].Value.ToInt(),
                                            FileName = syntaxTree.FileName,
                                            SyntaxTree = syntaxTree.SyntaxTree
                                        }).ToImmutableList();

            var missingVersions = AllApiVersions.Except(hasVersionStatements, item => item.MajorVersion, item => item.Version).ToImmutableList();

            var codeSample = missingVersions.Select(v => $".HasApiVersion(new ApiVersion({v}))").Flatten($"{Environment.NewLine}                                  ");

            var invalidEndpointMappings = (from missingVersion in missingVersions
                                           select new
                                           {
                                               Error = $@"
-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Missing:   {missingVersion}
-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:

 // Setup API versioning
var apiVersionSet = webApplication.NewApiVersionSet()
                                  {codeSample}
                                  .ReportApiVersions()
                                  .Build();
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                           }).ToImmutableList();

            Assert.IsTrue(invalidEndpointMappings.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_MAPI_00011

Please register all API versions used in the code. Background Swagger and any other ApiExplorer functionality
works only correct if all api versions is correctly used and all api versions are correctly registered.

Findings {invalidEndpointMappings.Count}': 

{invalidEndpointMappings.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
}
